import React from 'react';
import { useAuth } from '../contexts/AuthContext';

const Debug = () => {
  const { user } = useAuth();

  const userData = localStorage.getItem('user');
  const token = localStorage.getItem('token');

  return (
    <div style={{ 
      position: 'fixed', 
      top: '10px', 
      right: '10px', 
      background: 'white', 
      border: '1px solid black', 
      padding: '10px',
      zIndex: 9999,
      fontSize: '12px',
      maxWidth: '300px'
    }}>
      <h4>Debug Info:</h4>
      <p><strong>User from context:</strong> {JSON.stringify(user)}</p>
      <p><strong>User from localStorage:</strong> {userData}</p>
      <p><strong>Token exists:</strong> {!!token}</p>
      {token && (
        <p><strong>Token payload:</strong> {JSON.stringify(JSON.parse(atob(token.split('.')[1])))}</p>
      )}
    </div>
  );
};

export default Debug;
